-- Kuentas · Modelo de factura de MERCADONET y MILBROTES (26-nov-2026). Iván: «adaptar el modelo de factura de
-- MERCADONET y generar el modelo de factura de MILBROTES». Guarda en el perfil de cada empresa su logo, colores y pie
-- (profiles.factura_marca, migración 20261126100000); desde ese momento sus PDF salen con su modelo.
-- Supabase → proyecto kuentas-eu → SQL Editor → pegar todo → Run. Se puede repetir.
-- Volver al diseño de Kuentas: update public.profiles set factura_marca = null where id = '<id de la cuenta>';
with marcas (correo, marca) as (
  values
    ('info@mercadonet.es', '{"logo": "data:image/png;base64,", "colorPrincipal": "#787068", "colorTitulo": "#b7a17a", "colorSuave": "#ebe8e1", "pie": "Mercadonet Global S.L. · NIF B98407901 · Partida Cortixelles, 98 · 46900 Torrent (Valencia)"}'::jsonb),
    ('info@milbrotes.com', '{"logo": "data:image/jpeg;base64,", "colorPrincipal": "#366d33", "colorTitulo": "#14281d", "colorSuave": "#f2f7f0", "pie": "MILBROTES, S.L. · NIF B05772710 · Calle Belalcázar, 14, 28006 Madrid · Inscrita en el Registro Mercantil de Madrid, hoja M-899621 · www.milbrotes.com"}'::jsonb)
)
update public.profiles p
   set factura_marca = m.marca
  from marcas m
  join auth.users u on lower(u.email) = m.correo
 where p.id = u.id
returning m.correo, p.name, p.factura_marca->>'colorPrincipal' as color_principal, length(p.factura_marca->>'logo') as logo_caracteres;
